    private fun lossless(value: Any?): Any? = when (value) {
        is String -> {
            var i = 0
            var unpaired = false
            while (i < value.length) {
                val c = value[i++]
                if (Character.isHighSurrogate(c) && i < value.length && Character.isLowSurrogate(value[i])) i++
                else if (Character.isSurrogate(c)) unpaired = true
            }
            if (unpaired) mapOf("\$utf16" to value.map { it.code }) else value
        }
        is Map<*, *> -> value.entries.associateTo(LinkedHashMap()) { (k, v) -> k.toString() to lossless(v) }
        is List<*> -> value.map { lossless(it) }
        else -> value
    }
