        "R3-sol-5-negative" to listOf("k: \"-1\"" to 1),
        "R3-sol-5-exponent" to listOf("k: \"1e1\"" to 1),
        "R3-sol-5-plus" to listOf("k: \"+1\"" to 1),
        "R3-sol-5-negative-decimal" to listOf("k: \"-1.0\"" to 1),
        "R3-sol-5-integer-overflow" to listOf("k: \"9223372036854775808\"" to 1),
        "R3-sol-6-parent" to listOf("k: \"/a/../b\"" to 1),
        "R3-sol-6-dot" to listOf("k: \"/a/./b\"" to 1),
        "R3-sol-6-root-dot" to listOf("k: \"/.\"" to 1),
        "R3-sol-6-root-parent" to listOf("k: \"/../x\"" to 1),
        "R3-sol-7-nul" to listOf("k: !!binary \"\\x00\"" to 1),
        "R3-sol-7-newline" to listOf("k: !!binary \"QUJD\\nREVG\"" to 1),
        "R3-sol-8-empty" to listOf("\"\"" to 1),
        "R3-sol-8-blank" to listOf("\" \"" to 1)
    )
    fun generate(out: File, round3: Boolean = false) {
        val table = JsonlTable(out.nameWithoutExtension, "WP 0.3b round-1/2/3 review regressions, SnakeYAML 2.2 / Jackson 2.17.2 / Kotlin readText; \$utf16 objects transport unpaired Java surrogates losslessly.", mapOf("input_gen" to "concatenate [text, count] pairs", "input_bytes" to "raw unsigned bytes, decoded by JDK UTF-8 InputStreamReader", "decoded" to "JDK text for byte-input rows", "tokens" to "same as yaml-corpus, plus error marks by role"))
        fun add(id: String, segments: List<Pair<String, Int>>, bytes: ByteArray? = null) {
            val text = bytes?.let { InputStreamReader(ByteArrayInputStream(it), StandardCharsets.UTF_8).use { r -> r.readText() } }
                ?: buildString { for ((s, n) in segments) repeat(n) { append(s) } }
            val tokens = YamlCorpus.tokens(text).toMutableMap()
            // Read role-bearing marks directly from exceptions, rather than guessing
            // them from snippets (which suppress equal context/problem marks).
            val mapper = marathonfileMapper(FixedTimeProvider(YamlCorpus.NOW), File("/"))
            try { mapper.createParser(text).use { p -> while (p.nextToken() != null) {} } }
            catch (t: Throwable) {
                @Suppress("UNCHECKED_CAST")
                val err = (tokens["error"] as Map<String, Any?>).toMutableMap()
                fun mark(m: com.fasterxml.jackson.dataformat.yaml.snakeyaml.error.Mark?) = m?.let { listOf(it.line + 1, it.column + 1) }
                val marked = t as? MarkedYAMLException
                val loc = (t as? JsonProcessingException)?.location
                err["marks"] = linkedMapOf("context" to mark(marked?.contextMark), "problem" to mark(marked?.problemMark), "location" to loc?.let { listOf(it.lineNr, it.columnNr) })
                tokens["error"] = err
            }
            val row = linkedMapOf<String, Any?>("id" to id, "family" to "review", "note" to if (id.startsWith("R3-")) "round-3 regression" else if (id.startsWith("R2-")) "round-2 regression" else "round-1 regression", "tokens" to tokens,
                "bind" to YamlCorpus.simpleTargets.associate { (name, cls) -> name to YamlCorpus.bind(text, cls, true) }.toSortedMap())
            if (bytes != null) { row["input_bytes"] = bytes.map { it.toInt() and 255 }; row["decoded"] = text }
            else row["input_gen"] = segments.map { it.toList() }
            @Suppress("UNCHECKED_CAST")
            table.add(lossless(row) as Map<String, Any?>)
        }
        if (round3) {
            for ((id, segments) in round3Cases) add(id, segments)
            table.writeTo(out.parentFile.also { it.mkdirs() }).renameTo(out)
            return
        }
        for ((id, segments) in cases) add(id, segments)
        for ((id, segments) in round2Cases) add(id, segments)
        val malformed = listOf(
            "ff" to listOf(0xff), "surrogate" to listOf(0xed,0xa0,0x80), "truncated" to listOf(0xe2,0x82),
            "overlong" to listOf(0xc0,0xaf), "bad-second" to listOf(0xe2,0x41,0x80), "bad-third" to listOf(0xe2,0x82,0x41),
            "overlong-three" to listOf(0xe0,0x80,0x80), "out-of-range" to listOf(0xf4,0x90,0x80,0x80),
            "short-surrogate" to listOf(0xed,0xa0), "truncated-four" to listOf(0xf0,0x9f,0x98),
            "encoded-low-surrogate" to listOf(0xed,0xb0,0x80), "valid-supplementary" to listOf(0xf0,0x9f,0x98,0x80)
        )
        for ((id, b) in malformed) add("UTF8-$id", emptyList(), (listOf(0x6b,0x3a,0x20)+b+listOf(10)).map { it.toByte() }.toByteArray())
        add("R2-bytes-138", emptyList(), listOf(107,58,32,237,160,128,10).map { it.toByte() }.toByteArray())
        add("R2-bytes-139", emptyList(), listOf(107,58,32,192,175,10).map { it.toByte() }.toByteArray())
        add("R2-bytes-140", emptyList(), listOf(107,58,32,240,128,128,128,10).map { it.toByte() }.toByteArray())
        add("R2-bytes-141", emptyList(), listOf(107,58,32,226,130,10).map { it.toByte() }.toByteArray())
        add("R2-bytes-142", emptyList(), listOf(107,58,32,128,10).map { it.toByte() }.toByteArray())
        add("R2-bytes-143", emptyList(), listOf(107,58,32,237,160,65,10).map { it.toByte() }.toByteArray())
        add("R2-bytes-144", emptyList(), listOf(107,58,32,237,65,128,10).map { it.toByte() }.toByteArray())
        add("R2-bytes-145", emptyList(), listOf(107,58,32,244,143,191,10).map { it.toByte() }.toByteArray())
        add("R2-bytes-146", emptyList(), listOf(107,58,32,245,128,128,128,10).map { it.toByte() }.toByteArray())
        add("R2-bytes-147", emptyList(), listOf(107,58,32,224,159,191,10).map { it.toByte() }.toByteArray())
        table.writeTo(out.parentFile.also { it.mkdirs() }).renameTo(out)
    }
}
